using System;
using System.Collections.Generic;
using System.Linq;
using GuildAdventure.Game.Save;
using GuildAdventure.Game.Core;
namespace GuildAdventure.Game.Battle
{
 public sealed class BattleAttackProposal{public string reservationId,sourceId,targetId,skillId;public int hitCount=1;public DamageType damageType;public double criticalRatePercent,accuracy,evasion,magicAccuracy,magicResistance,baseDamage,damageResistance,criticalBonusDamagePercent=HitCritical.InitialCriticalBonusDamagePercent;public double criticalBonusReduction,formationMultiplier=1,randomMultiplier=1;public IEnumerable<ElementShare> elementShares;public IDictionary<Element,double> elementResistances;public bool blockEligible;public double blockRate,blockCutRate;public List<BarrierLayer> barriers=new List<BarrierLayer>();public Func<int,int,int?> fatalResolver;public Func<ReactiveTriggerRequest,int,int,int?> executeFatalReactive;public double hpAbsorbRate,mpAbsorbRate,reflectionRate;public IEnumerable<TriggerRegistration> triggerRegistrations;public TriggerActionContext triggerActionContext;public IRandomSource passiveTriggerRng;public Action<ReactiveTriggerRequest> executeReactive;}
 public sealed class BattleStepResult{public bool ok;public string reason;public ActionReservationSaveRecord reservation;public ResolvedHitSaveRecord resolvedHit;public List<ResolvedHitSaveRecord> resolvedHits=new List<ResolvedHitSaveRecord>();public List<BarrierLayer> remainingBarriers=new List<BarrierLayer>();public int barrierAbsorbed,hpAbsorbed,mpAbsorbed,reflectedDamage;public List<BattleTriggerDispatch> triggerDispatches=new List<BattleTriggerDispatch>();public int reactiveExecuted,reactiveSkipped;public string reactiveStopReason;}
 public static class BattleStepExecutor
 {
  public static BattleStepResult ExecuteAttack(BattleSnapshotSaveRecord snapshot,BattleAttackProposal p,IRandomSource criticalRng,IRandomSource hitRng,IRandomSource blockRng)=>ExecuteAttack(snapshot,p,null,criticalRng,hitRng,blockRng);
  public static BattleStepResult ExecuteAttack(BattleSnapshotSaveRecord snapshot,BattleAttackProposal p,ActionReservationSaveRecord reservation,IRandomSource criticalRng,IRandomSource hitRng,IRandomSource blockRng){if(snapshot==null||p==null||criticalRng==null||hitRng==null)return Fail("BATTLE_STEP_INPUT_INVALID");if(p.blockEligible&&p.blockRate>0&&blockRng==null)return Fail("BATTLE_STEP_BLOCK_RNG_MISSING");var source=snapshot.actors.Find(x=>x.actorId==p.sourceId);var target=snapshot.actors.Find(x=>x.actorId==p.targetId);if(source==null||target==null)return Fail("BATTLE_STEP_ACTOR_MISSING");if(!source.alive||source.hp<=0)return Fail("BATTLE_STEP_SOURCE_DEAD");if(!target.alive||target.hp<=0)return Fail("BATTLE_STEP_TARGET_DEAD");if(string.IsNullOrWhiteSpace(p.reservationId))return Fail("BATTLE_STEP_ID_MISSING");if(p.hitCount<=0)return Fail("BATTLE_STEP_HIT_COUNT_INVALID");if(reservation==null){if(snapshot.actionReservations.Exists(x=>x.reservationId==p.reservationId))return Fail("BATTLE_STEP_ID_DUPLICATE");reservation=new ActionReservationSaveRecord{reservationId=p.reservationId,actorId=p.sourceId,skillId=p.skillId,startTick=snapshot.tick,completeTick=snapshot.tick,fixedTargetIds=new List<string>{p.targetId},usageConditions=new UsageConditionsSaveRecord()};snapshot.actionReservations.Add(reservation);}else{if(reservation.reservationId!=p.reservationId||reservation.actorId!=p.sourceId||reservation.skillId!=p.skillId)return Fail("BATTLE_STEP_RESERVATION_MISMATCH");if(!reservation.fixedTargetIds.Contains(p.targetId))return Fail("BATTLE_STEP_TARGET_NOT_RESERVED");var existing=snapshot.actionReservations.Find(x=>x.reservationId==reservation.reservationId);if(existing!=null&&!ReferenceEquals(existing,reservation))return Fail("BATTLE_STEP_ID_DUPLICATE");if(existing==null)snapshot.actionReservations.Add(reservation);}var actionContext=p.triggerActionContext??new TriggerActionContext{actionId=p.reservationId};if(string.IsNullOrWhiteSpace(actionContext.actionId))actionContext.actionId=p.reservationId;var result=new BattleStepResult{ok=true,reservation=reservation};var snapshotBarriers=target.barrierLayers.OrderBy(x=>x.appliedTick).ThenBy(x=>x.sequence).ThenBy(x=>x.id,StringComparer.Ordinal).Select(x=>new BarrierLayer{id=x.id,remaining=x.remaining}).ToList();var barriers=snapshotBarriers.Count>0?snapshotBarriers:(p.barriers==null?new List<BarrierLayer>():new List<BarrierLayer>(p.barriers));var fixedOrder=BattleEffectLifecycle.BuildFixedOrder(snapshot);for(var i=0;i<p.hitCount;i++){if(!target.alive||target.hp<=0)break;var one=ResolveHit(snapshot,p,source,target,i,barriers,actionContext,fixedOrder,criticalRng,hitRng,blockRng);if(!one.ok)return Fail(one.reason);result.resolvedHit=one.resolvedHit;result.resolvedHits.Add(one.resolvedHit);result.remainingBarriers=one.remainingBarriers;result.barrierAbsorbed+=one.barrierAbsorbed;result.hpAbsorbed+=one.hpAbsorbed;result.mpAbsorbed+=one.mpAbsorbed;result.reflectedDamage+=one.reflectedDamage;barriers=one.remainingBarriers;snapshot.resolvedHits.Add(one.resolvedHit);var blocked=one.resolvedHit.block!=null&&one.resolvedHit.block.json!=null&&one.resolvedHit.block.json.Contains("true");var dispatches=BattleEffectLifecycle.DispatchResolvedHitEvents(one.resolvedHit,p.triggerRegistrations,fixedOrder,p.skillId,actionContext,blocked,!target.alive||target.hp<=0);result.triggerDispatches.AddRange(dispatches);TriggerActivationRuntime.EnqueueBatch(actionContext,dispatches);var drain=TriggerActivationRuntime.Drain(actionContext,p.passiveTriggerRng,p.executeReactive);result.reactiveExecuted+=drain.executed;result.reactiveSkipped+=drain.skipped;if(!drain.ok){result.reactiveStopReason=drain.reason;if(drain.reason==TriggerActivationRuntime.LimitReached)break;}if(!source.alive||source.hp<=0)break;}return result;}
  static BattleStepResult ResolveHit(BattleSnapshotSaveRecord snapshot,BattleAttackProposal p,BattleActorSaveRecord source,BattleActorSaveRecord target,int hitIndex,List<BarrierLayer> barriers,TriggerActionContext actionContext,IReadOnlyDictionary<string,int> fixedOrder,IRandomSource criticalRng,IRandomSource hitRng,IRandomSource blockRng){var hit=HitCritical.Resolve(p.criticalRatePercent,p.damageType,p.accuracy,p.evasion,p.magicAccuracy,p.magicResistance,()=>criticalRng.Next01("CRITICAL"),()=>hitRng.Next01("HIT"));var resolved=new ResolvedHitSaveRecord{actionId=p.reservationId,hitIndex=hitIndex,sourceId=p.sourceId,targetId=p.targetId,judgement=hit.critical?"CRITICAL":hit.hit?"HIT":"MISS",perHitDamage=0,committedHp=target.hp,actualHpLoss=0};resolved.rngRolls.Add(hit.criticalRoll/100d);if(hit.hitRoll.HasValue)resolved.rngRolls.Add(hit.hitRoll.Value/100d);if(!hit.hit)return new BattleStepResult{ok=true,resolvedHit=resolved,remainingBarriers=barriers};var damage=DamageDefense.ResolveFinalDamage(p.baseDamage,p.damageResistance,hit.critical,p.criticalBonusDamagePercent,p.criticalBonusReduction,p.elementShares,p.elementResistances,p.formationMultiplier,p.randomMultiplier);resolved.perHitDamage=damage.finalDamage;double? blockRoll=null;if(p.blockEligible&&p.blockRate>0){blockRoll=blockRng.Next01("BLOCK");resolved.rngRolls.Add(blockRoll.Value);}var block=DamageDefense.ResolveBlock(damage.finalDamage,p.blockEligible,p.blockRate,p.blockCutRate,blockRoll);resolved.block=new OpaqueContractPayload{json=block.blocked?"{\"blocked\":true}":"{\"blocked\":false}"};Func<int,int,int?> fatal=p.fatalResolver;if(p.executeFatalReactive!=null)fatal=(before,projected)=>{var fr=FatalDamageTriggerRuntime.Resolve(before,projected,p.sourceId,p.sourceId,p.targetId,p.skillId,hitIndex,p.triggerRegistrations,fixedOrder,actionContext,p.passiveTriggerRng,p.executeFatalReactive);return fr.prevented?(int?)fr.hpAfter:null;};var committed=BattleDamageRuntime.Commit(target,block.damage,barriers,fatal,true);resolved.committedHp=committed.hpAfter;resolved.actualHpLoss=committed.actualHpLoss;resolved.barrier=new OpaqueContractPayload{json="{\"absorbed\":"+committed.barrierAbsorbed+"}"};int hpAbsorb=(int)Math.Ceiling(committed.actualHpLoss*Math.Max(0,p.hpAbsorbRate)),mpAbsorb=(int)Math.Ceiling(committed.actualHpLoss*Math.Max(0,p.mpAbsorbRate)),reflected=(int)Math.Floor(committed.actualHpLoss*Math.Max(0,p.reflectionRate));source.hp=Math.Min(source.maxHp,source.hp+hpAbsorb);source.mp=Math.Min(source.maxMp,source.mp+mpAbsorb);if(reflected>0)BattleDamageRuntime.Commit(source,reflected,ReflectionFatalResolver(p,source,target,hitIndex,actionContext,fixedOrder),false);return new BattleStepResult{ok=true,resolvedHit=resolved,remainingBarriers=committed.remainingBarriers,barrierAbsorbed=committed.barrierAbsorbed,hpAbsorbed=hpAbsorb,mpAbsorbed=mpAbsorb,reflectedDamage=reflected};}
  static Func<int,int,int?> ReflectionFatalResolver(BattleAttackProposal p,BattleActorSaveRecord source,BattleActorSaveRecord reflector,int hitIndex,TriggerActionContext actionContext,IReadOnlyDictionary<string,int> fixedOrder){if(p.executeFatalReactive!=null)return (before,projected)=>{var fr=FatalDamageTriggerRuntime.Resolve(before,projected,reflector.actorId,p.sourceId,source.actorId,p.skillId,hitIndex,p.triggerRegistrations,fixedOrder,actionContext,p.passiveTriggerRng,p.executeFatalReactive);return fr.prevented?(int?)fr.hpAfter:null;};return p.fatalResolver;}
  static BattleStepResult Fail(string reason)=>new BattleStepResult{ok=false,reason=reason};
 }
}
